import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { readFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { mkdir } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));
const dbPath = process.env.DB_PATH || join(root, 'data', 'workboard.sqlite');
if (dbPath !== ':memory:') await mkdir(dirname(dbPath), { recursive: true });
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
)`);
const listProjects = db.prepare('SELECT id, name FROM projects ORDER BY id');
const getProject = db.prepare('SELECT id, name FROM projects WHERE id = ?');
const createProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
)`);
const listTasks = db.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
const createTask = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const getTask = db.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE id = ? AND project_id = ?');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');
const send = (res, status, body, type = 'application/json; charset=utf-8') => {
  res.writeHead(status, { 'Content-Type': type, 'X-Content-Type-Options': 'nosniff' });
  res.end(body);
};
const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  if (req.method === 'GET' && url.pathname === '/health') return send(res, 200, JSON.stringify({ status: 'ok' }));
  const taskRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/?$/);
  const taskUpdateRoute = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)\/?$/);
  if (taskRoute) {
    const projectId = Number(taskRoute[1]);
    if (!getProject.get(projectId)) return send(res, 404, JSON.stringify({ error: 'Project not found' }));
    if (req.method === 'GET') return send(res, 200, JSON.stringify(listTasks.all(projectId)));
    if (req.method === 'POST') {
      try {
        let raw = '';
        for await (const chunk of req) { raw += chunk; if (raw.length > 100_000) return send(res, 413, JSON.stringify({ error: 'Request too large' })); }
        const input = JSON.parse(raw || '{}');
        const title = typeof input.title === 'string' ? input.title.trim() : '';
        if (!title) return send(res, 400, JSON.stringify({ error: 'Task title is required' }));
        const result = createTask.run(projectId, title);
        return send(res, 201, JSON.stringify(getTask.get(result.lastInsertRowid, projectId)));
      } catch { return send(res, 400, JSON.stringify({ error: 'Invalid request' })); }
    }
  }
  if (taskUpdateRoute && req.method === 'PATCH') {
    const projectId = Number(taskUpdateRoute[1]), taskId = Number(taskUpdateRoute[2]);
    try {
      let raw = ''; for await (const chunk of req) { raw += chunk; if (raw.length > 100_000) return send(res, 413, JSON.stringify({ error: 'Request too large' })); }
      const input = JSON.parse(raw || '{}');
      if (typeof input.completed !== 'boolean') return send(res, 400, JSON.stringify({ error: 'Completion must be boolean' }));
      if (!getTask.get(taskId, projectId)) return send(res, 404, JSON.stringify({ error: 'Task not found' }));
      updateTask.run(input.completed ? 1 : 0, taskId, projectId);
      return send(res, 200, JSON.stringify(getTask.get(taskId, projectId)));
    } catch { return send(res, 400, JSON.stringify({ error: 'Invalid request' })); }
  }
  if (req.method === 'GET' && url.pathname === '/api/projects') return send(res, 200, JSON.stringify(listProjects.all()));
  if (req.method === 'POST' && url.pathname === '/api/projects') {
    try {
      let raw = '';
      for await (const chunk of req) {
        raw += chunk;
        if (raw.length > 100_000) return send(res, 413, JSON.stringify({ error: 'Request too large' }));
      }
      const input = JSON.parse(raw || '{}');
      const name = typeof input.name === 'string' ? input.name.trim() : '';
      if (!name) return send(res, 400, JSON.stringify({ error: 'Project name is required' }));
      const result = createProject.run(name);
      return send(res, 201, JSON.stringify(getProject.get(result.lastInsertRowid)));
    } catch {
      return send(res, 400, JSON.stringify({ error: 'Invalid request' }));
    }
  }
  if (req.method === 'GET' && url.pathname.startsWith('/projects/')) {
    const id = url.pathname.slice('/projects/'.length);
    if (!/^\d+$/.test(id)) return send(res, 404, 'Not found', 'text/plain; charset=utf-8');
    if (!getProject.get(Number(id))) return send(res, 404, 'Not found', 'text/plain; charset=utf-8');
  }
  if (req.method === 'GET' && url.pathname === '/') {
    try { return send(res, 200, await readFile(join(root, 'index.html'), 'utf8'), 'text/html; charset=utf-8'); }
    catch { return send(res, 500, 'Application unavailable', 'text/plain; charset=utf-8'); }
  }
  if (req.method === 'GET' && url.pathname === '/app.js') {
    try { return send(res, 200, await readFile(join(root, 'app.js'), 'utf8'), 'text/javascript; charset=utf-8'); }
    catch { return send(res, 404, 'Not found', 'text/plain; charset=utf-8'); }
  }
  if (req.method === 'GET' && url.pathname.startsWith('/projects/')) {
    try { return send(res, 200, await readFile(join(root, 'index.html'), 'utf8'), 'text/html; charset=utf-8'); }
    catch { return send(res, 500, 'Application unavailable', 'text/plain; charset=utf-8'); }
  }
  send(res, 404, JSON.stringify({ error: 'Not found' }));
});
const port = Number(process.env.PORT) || 8080;
server.listen(port, '0.0.0.0');

const app = document.querySelector('#app');

async function request(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Request failed');
  return data;
}

function element(tag, text, attributes = {}) {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  for (const [key, value] of Object.entries(attributes)) node.setAttribute(key, value);
  return node;
}

async function renderList() {
  app.replaceChildren(element('h1', 'Workboard'));
  const form = document.createElement('form');
  const input = element('input', undefined, { id: 'project-name', name: 'name', type: 'text' });
  input.setAttribute('aria-label', 'Project name');
  form.append(input, element('button', 'Create project', { type: 'submit' }));
  const error = element('p', '', { id: 'error', role: 'alert', hidden: '' });
  const list = element('section', undefined, { 'aria-label': 'Projects' });
  form.addEventListener('submit', async event => {
    event.preventDefault();
    error.hidden = true;
    try {
      await request('/api/projects', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name: input.value }) });
      input.value = '';
      await populateProjects(list);
    } catch (cause) {
      error.textContent = cause.message;
      error.hidden = false;
    }
  });
  app.append(form, error, list);
  await populateProjects(list);
}

async function populateProjects(list) {
  const projects = await request('/api/projects');
  list.replaceChildren(...projects.map(project => {
    const row = element('div', undefined, { 'data-testid': 'project-row' });
    row.append(element('span', project.name), element('button', 'Open project', { type: 'button' }));
    row.querySelector('button').addEventListener('click', () => { location.href = `/projects/${encodeURIComponent(project.id)}`; });
    return row;
  }));
}

async function renderProject(id) {
  const project = await request('/api/projects').then(projects => projects.find(item => String(item.id) === id));
  if (!project) { location.replace('/'); return; }
  const back = element('button', 'Projects', { type: 'button' });
  back.addEventListener('click', () => { location.href = '/'; });
  const heading = element('h1', project.name);
  const form = document.createElement('form');
  const input = element('input', undefined, { id: 'task-title', name: 'title', type: 'text' });
  input.setAttribute('aria-label', 'Task title');
  form.append(input, element('button', 'Create task', { type: 'submit' }));
  const error = element('p', '', { id: 'error', role: 'alert', hidden: '' });
  const filterLabel = element('label', 'Task filter', { for: 'task-filter' });
  const filter = element('select', undefined, { id: 'task-filter' });
  filter.setAttribute('aria-label', 'Task filter');
  for (const value of ['All', 'Open', 'Completed']) filter.append(element('option', value, { value }));
  const list = element('section', undefined, { 'aria-label': 'Tasks' });
  const refresh = async () => {
    const tasks = await request(`/api/projects/${encodeURIComponent(id)}/tasks`);
    const shown = tasks.filter(task => filter.value === 'All' || (filter.value === 'Completed') === Boolean(task.completed));
    list.replaceChildren(...shown.map(task => {
      const row = element('div', undefined, { 'data-testid': 'task-row' });
      row.append(element('span', task.title));
      const checkbox = element('input', undefined, { type: 'checkbox' });
      checkbox.checked = Boolean(task.completed);
      checkbox.setAttribute('aria-label', `Complete ${task.title}`);
      checkbox.addEventListener('change', async () => {
        try {
          await request(`/api/projects/${encodeURIComponent(id)}/tasks/${encodeURIComponent(task.id)}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
          await refresh();
        } catch { checkbox.checked = !checkbox.checked; }
      });
      row.append(checkbox);
      return row;
    }));
  };
  filter.addEventListener('change', () => refresh().catch(() => {}));
  form.addEventListener('submit', async event => {
    event.preventDefault(); error.hidden = true;
    try {
      await request(`/api/projects/${encodeURIComponent(id)}/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title: input.value }) });
      input.value = ''; await refresh();
    } catch (cause) { error.textContent = cause.message; error.hidden = false; }
  });
  app.replaceChildren(back, heading, form, error, filterLabel, filter, list);
  await refresh();
}

const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);
if (match) renderProject(match[1]).catch(() => { location.replace('/'); });
else renderList().catch(() => { app.textContent = 'Unable to load projects.'; });

